    definition: u32,
    width: u64,
    height: u64,
}

fn key(definition: ElementId, viewport: [f64; 2], offset: usize) -> Result<Key> {
    if definition.0 > u32::MAX as usize {
        return Err(limit(LimitKind::PaintVisits, offset));
    }
    if !viewport
        .into_iter()
        .all(|value| value.is_finite() && value > 0.0)
    {
        return Err(unsupported(offset));
    }
    Ok(Key {
        definition: definition.0 as u32,
        width: viewport[0].to_bits(),
        height: viewport[1].to_bits(),
    })
}

fn hash(key: Key) -> usize {
    let mut value =
        u64::from(key.definition) ^ key.width ^ key.height.wrapping_add(0x9e37_79b9_7f4a_7c15);
    value ^= value >> 30;
    value = value.wrapping_mul(0xbf58_476d_1ce4_e5b9);
    value ^= value >> 27;
    value = value.wrapping_mul(0x94d0_49bb_1331_11eb);
    value ^= value >> 31;
    value as usize & (CACHE_SLOTS - 1)
}

pub(crate) fn token_visit(
    cache: &mut PaintCache,
    control: &mut PaintControl<'_>,
    offset: usize,
) -> Result<()> {
    let next = cache
        .token_visits
        .checked_add(1)
        .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
    if next > MAX_TOKEN_VISITS {
        return Err(limit(LimitKind::PaintVisits, offset));
    }
    control
        .charge(WorkKind::TokenVisit, 1)
        .map_err(|_| limit(LimitKind::Work, offset))?;
    cache.token_visits = next;
    Ok(())
    let cycle = resolve_fill(
        &mut ctx,
        span(bytes, b"url(#a)"),
        &edge,
        affine_identity(),
        [10., 10.],
        &mut work,
    )
    .unwrap_err();
    assert_eq!(cycle.kind, ErrorKind::Unsupported);
    let malformed = b"<svg><linearGradient id='g'><stop offset='.8'/><stop offset='.2'/></linearGradient><rect fill='url(#g)'/></svg>";
    let source = owner(malformed);
    let doc = LexicalDocument::parse(source.clone(), 1 << 20, &mut work).unwrap();
    let mut shared = DecodeSource::new(&doc, &mut work).unwrap();
    let mut cache = PaintCache::default();
    let mut ledger = ChargeLedger::new(&source, 1 << 24, 64).unwrap();
    let mut ctx = ResolveContext {
